package com.example.demo;

import java.util.ArrayList;
import java.util.List;

import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.GetMapping;

@Controller
public class CatalogueController {
	
	@GetMapping("/")
	public String show_Catalogue(Model model) {
		Products p1=new Products("Dell","High Performance","data:image/jpeg;base64,",30000 );
		Products p2=new Products("HP","Good Performance","data:image/jpeg;base64," , 27000);
		Products p3=new Products("Window","High Peerformance","data:image/jpeg;base64,"  ,32000);
		Products p4=new Products("Lenovo","High Performance","data:image/jpeg;base64,"  , 31000);
		
		List<Products> productList=new ArrayList<Products>();
		productList.add(p1);
		productList.add(p4);
		productList.add(p3);
		productList.add(p2);
		model.addAttribute("products",productList);
		return "catalogue";
	}
}
